-- AddCheck (hand-written): each range has min <= max. NULL passes (no limit on that side).
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_price_range_check"
    CHECK ("priceMin" >= 0 AND "priceMax" >= 0 AND "priceMin" <= "priceMax");
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_yearBuilt_range_check"
    CHECK ("yearBuiltMin" >= 1800 AND "yearBuiltMax" >= 1800 AND "yearBuiltMin" <= "yearBuiltMax");
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_beds_range_check"
    CHECK ("bedsMin" BETWEEN 0 AND 20 AND "bedsMax" BETWEEN 0 AND 20 AND "bedsMin" <= "bedsMax");
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_baths_range_check"
    CHECK ("bathsMin" BETWEEN 0 AND 20 AND "bathsMax" BETWEEN 0 AND 20 AND "bathsMin" <= "bathsMax");
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_sqft_range_check"
    CHECK ("sqftMin" > 0 AND "sqftMax" > 0 AND "sqftMin" <= "sqftMax");
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_units_range_check"
    CHECK ("unitsMin" BETWEEN 2 AND 500 AND "unitsMax" BETWEEN 2 AND 500 AND "unitsMin" <= "unitsMax");

-- AddCheck (hand-written): a list criterion is NULL (any) or names at least one value.
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_propertyTypes_check" CHECK (cardinality("propertyTypes") > 0);
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_conditionsAccepted_check"
    CHECK (cardinality("conditionsAccepted") > 0);
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_programsAccepted_check"
    CHECK (cardinality("programsAccepted") > 0);

-- AddCheck (hand-written): the remaining single-value limits.
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_repairMax_check" CHECK ("repairMax" >= 0);
ALTER TABLE "BuyBox" ADD CONSTRAINT "BuyBox_closeWithinDays_check" CHECK ("closeWithinDays" BETWEEN 7 AND 120);

-- CreateIndex (hand-written): at most one default box per investor (the one the import updates).
CREATE UNIQUE INDEX "BuyBox_one_default_per_investor" ON "BuyBox"("investorId") WHERE "isDefault";
